CREATE FUNCTION s.pprb_retable1()
RETURNS TABLE(a integer, b text)
LANGUAGE plpgsql AS $$
BEGIN
  a := 1; b := 'x'; RETURN NEXT;
  a := 2; b := 'y'; RETURN NEXT;
END $$;

CREATE FUNCTION s.pprb_retable2()
RETURNS TABLE(n integer)
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY SELECT generate_series(1,4);
END $$;

CREATE FUNCTION s.pprb_retable3()
RETURNS TABLE(id bigint, name text)
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY SELECT t.id, t.name FROM s.t;
END $$;

CREATE FUNCTION s.pprb_retable4()
RETURNS TABLE(n integer)
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY EXECUTE 'SELECT generate_series(1,5)';
END $$;

CREATE FUNCTION s.pprb_retable5()
RETURNS TABLE(x integer, y integer)
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY SELECT a, b FROM (VALUES (1,2),(3,4)) AS v(a,b);
END $$;

CREATE FUNCTION s.pprb_retable6(lim integer)
RETURNS TABLE(n integer)
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY EXECUTE 'SELECT generate_series(1,$1)' USING lim;
END $$;

CREATE FUNCTION s.pprb_retable7()
RETURNS TABLE(m s.mood)
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY SELECT status FROM s.t;
END $$;
